using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;using System.Collections.Generic;using System.Diagnostics;
namespace FleetLab {
    public sealed class SoloSetup:UserControl {
        internal readonly SoloProgram Program;internal SoloState State {get;private set;}internal readonly SetupCanvas Canvas=new SetupCanvas();internal readonly Button FadeButton=new Button(),BackButton=new Button();
        public event Action StartClassicRequested,ReturnRequested;
        readonly IndexedImage card;readonly Label note=new Label();readonly ClassicPracticeScene scene;readonly Timer timer=new Timer();readonly Stopwatch clock=Stopwatch.StartNew();Bitmap image;long last,elapsed;int scroll,hover=-1;bool disposed;
        internal int Selected {get;private set;}internal int Factor {get;private set;}internal bool Revealing {get;private set;}internal bool HasOpened {get;private set;}internal Bitmap CurrentImage {get{return image;}}internal int DescriptionPage {get{return scroll;}}internal int HoveredIndex {get{return hover>=10?hover:-1;}}
        public SoloSetup(string assets){Dock=DockStyle.Fill;BackColor=Color.FromArgb(10,22,34);ForeColor=Color.WhiteSmoke;card=Assets.Pcx(Path.Combine(assets,"Graphics","E2_SOLO.PCX"));var reserved=ClassicPalette.Gameplay(File.ReadAllBytes(Path.Combine(assets,"Graphics","ISLAND.COL")));for(int i=0;i<256;i++)if(i<10||i>245)card.Palette[i]=reserved[i];scene=new ClassicPracticeScene(assets);Program=scene.Program;State=new SoloState(Program);
            Canvas.Owner=this;Canvas.Dock=DockStyle.Fill;Canvas.AccessibleName="Original Practice setup; arrows select, Enter activates; only Classic is playable";Controls.Add(Canvas);var head=new Panel{Dock=DockStyle.Top,Height=96,Padding=new Padding(12,4,12,2)};Controls.Add(head);note.Dock=DockStyle.Fill;head.Controls.Add(note);var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=39,WrapContents=false};head.Controls.Add(buttons);Add(buttons,FadeButton,"Pause fade",delegate{if(Revealing)Pause();else if(Factor<64){Revealing=true;last=clock.ElapsedMilliseconds;UpdateFade();Canvas.Focus();}});Add(buttons,BackButton,"Back to title",delegate{Back();});timer.Interval=16;timer.Tick+=delegate{long now=clock.ElapsedMilliseconds,dt=now-last;last=now;if(disposed||!Revealing||!Visible)return;elapsed+=dt;bool changed=false;while(elapsed>=40&&Revealing){elapsed-=40;if(Factor==64)Revealing=false;else Factor+=4;changed=true;}if(changed)Render();};timer.Start();Reset();
        }
        static void Add(Control p,Button b,string text,EventHandler click){b.Text=text;b.AutoSize=true;b.Height=32;b.BackColor=Color.FromArgb(31,56,75);b.ForeColor=Color.WhiteSmoke;b.FlatStyle=FlatStyle.Flat;b.Click+=click;p.Controls.Add(b);}
        public void Begin(){if(disposed)return;State=new SoloState(Program);HasOpened=true;Selected=7;scroll=0;hover=-1;Factor=12;elapsed=0;Revealing=true;last=clock.ElapsedMilliseconds;Canvas.ClearPress();note.Text="Choose a Practice mission. Classic is playable; the other missions are previews.";Render();Canvas.Focus();}
        public void Reset(){if(disposed)return;HasOpened=false;Revealing=false;Canvas.ClearPress();Bitmap old=image;image=null;if(old!=null)old.Dispose();Canvas.Invalidate();}
        public void Pause(){if(disposed)return;Revealing=false;Canvas.ClearPress();UpdateFade();}
        internal void FinishReveal(){if(disposed)return;Factor=64;Revealing=false;Render();}
        void UpdateFade(){FadeButton.Enabled=HasOpened&&Factor<64;FadeButton.Text=Revealing?"Pause fade":Factor==64?"Fade complete":"Resume fade";}
        void Back(){if(disposed)return;Pause();if(ReturnRequested!=null)ReturnRequested();}
        internal void Select(int index){if(disposed||index<0||index>=14)return;Selected=index;Render();}
        internal bool Key(Keys key){if(disposed||!HasOpened||Factor<64)return false;if(key==Keys.Escape){Back();return true;}if(key==Keys.Up||key==Keys.Down||key==Keys.Left||key==Keys.Right){Select((Selected+(key==Keys.Up||key==Keys.Left?13:1))%14);return true;}if(key==Keys.Enter||key==Keys.Space){Activate(Selected);return true;}return false;}
        internal void Activate(int index){if(disposed||!HasOpened||Factor<64||index<0||index>=14)return;Selected=index;int action=Program.Buttons[index].Action;switch(action){case 99:break;case 21:case 22:note.Text="World Domination and Scenario setup are not reconstructed. Practice → Classic is playable.";break;case 23:case 24:case 25:State.SelectPlayers(action-21);note.Text=State.Type==20?"Classic supports one opponent. Start Game opens the current recovered Classic deployment.":"This Practice mission is a preview; its real-time simulation is not implemented.";break;case 26:State.SelectType(20);scroll=0;note.Text="Classic selected: one opponent. Start Game uses recovered Classic rules and your current AI/display settings.";break;case 1:case 2:case 3:State.SelectType(action);scroll=0;note.Text="This Practice mission is a preview; its real-time simulation is not implemented.";break;case 27:if(State.Playable){if(StartClassicRequested!=null)StartClassicRequested();return;}note.Text="Only Classic can start in this build. Select Classic on the right, then Start Game.";break;case 28:Back();return;case 29:scroll=Math.Max(0,scroll-12);break;case 30:if(scroll<24&&ClassicMenuText.ReadRows(ClassicMenuText.Format(Program.Description(State.Type)))[scroll+12].Length!=0)scroll+=12;break;}Render();}
        void Render(){if(disposed||!HasOpened)return;Canvas.AccessibleDescription=Program.Description(State.Type);var indexed=scene.Compose(State.Type,State.Players,scroll,HoveredIndex);indexed.Palette=ClassicPalette.FadeDisplay(card.Palette,Factor);Bitmap next=indexed.Bitmap();Bitmap old=image;image=next;Canvas.Invalidate();if(old!=null)old.Dispose();UpdateFade();}
        protected override void Dispose(bool disposing){if(disposing&&!disposed){disposed=true;timer.Stop();timer.Dispose();HasOpened=Revealing=false;Canvas.ClearPress();var old=image;image=null;if(old!=null)old.Dispose();}base.Dispose(disposing);}
        internal sealed class SetupCanvas:Control {
            internal SoloSetup Owner;int pressed=-1;public SetupCanvas(){DoubleBuffered=true;ResizeRedraw=true;TabStop=true;BackColor=Color.Black;}
            internal RectangleF Bounds4x3 {get{float s=Math.Min(Width/640f,Height/480f);return new RectangleF((Width-640*s)/2,(Height-480*s)/2,640*s,480*s);}}
            internal int Hit(int x,int y){var b=Bounds4x3;if(b.Width<=0||x<b.Left||y<b.Top||x>=b.Right||y>=b.Bottom)return -1;return Owner.Program.Hit((int)((x-b.X)*640/b.Width),(int)((y-b.Y)*480/b.Height));}
            internal void ClearPress(){pressed=-1;}
            protected override bool IsInputKey(Keys key){return key==Keys.Up||key==Keys.Down||key==Keys.Left||key==Keys.Right||base.IsInputKey(key);}
            protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Left&&Owner.HasOpened&&Owner.Factor==64){Focus();pressed=Hit(e.X,e.Y);}}
            protected override void OnMouseUp(MouseEventArgs e){int at=pressed;base.OnMouseUp(e);ClearPress();if(e.Button==MouseButtons.Left&&at>=0&&Hit(e.X,e.Y)==at)Owner.Activate(at);}
            protected override void OnMouseCaptureChanged(EventArgs e){base.OnMouseCaptureChanged(e);if(!Capture)ClearPress();}
            protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);int at=Hit(e.X,e.Y);if(at!=Owner.hover){Owner.hover=at;Owner.Render();}}
            protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Owner==null||Owner.image==null)return;e.Graphics.InterpolationMode=InterpolationMode.NearestNeighbor;e.Graphics.PixelOffsetMode=PixelOffsetMode.Half;var b=Bounds4x3;e.Graphics.DrawImage(Owner.image,b);if(Focused&&Owner.Factor==64){var at=Owner.Program.Buttons[Owner.Selected].Bounds;using(var pen=new Pen(Color.Gold,1))e.Graphics.DrawRectangle(pen,b.X+at.X*b.Width/640,b.Y+at.Y*b.Height/480,at.Width*b.Width/640,at.Height*b.Height/480);}}
        }
    }
}
